import {AngleModel,pointerWorld,TIERS,quizQuestion,displayValues} from './angle-model.js?v=7';
import {mountCalculator} from './calculator-ui.js?v=8';
export function mountAngleExplorer({trigger,language=()=> 'en'}){
 const dialog=document.createElement('dialog');dialog.id='angleExplorer';dialog.className='angle-explorer';document.body.append(dialog);
 const models={straight:new AngleModel('straight'),circle:new AngleModel('circle')};let mode='straight',screen='library',shown=false,q=null,attempts=0,complete=false,tier=1,active=null,view={x:0,y:0,zoom:1},camera={x:0,y:0,zoom:1};
 const tr=(a,b)=>language()==='bm'?b:a,model=()=>models[mode],get=id=>dialog.querySelector('#'+id);
 const button=(id,a,b)=>`<button id="${id}">${tr(a,b)}</button>`;
 const point=(angle,r)=>({x:Math.cos(angle*Math.PI/180)*r,y:-Math.sin(angle*Math.PI/180)*r});
 function geometry(){if(screen!=='quiz')return{rays:model().rays,regions:model().regions(),rotation:0};let a=0;return{rotation:q.rotation,rays:q.values.map((v,i)=>{const r={id:'q'+i,angle:a,isFixed:true};a+=v;return r}).concat(mode==='straight'?[{id:'end',angle:180,isFixed:true}]:[]),regions:q.values.map((v,i)=>({start:q.values.slice(0,i).reduce((s,n)=>s+n,0),currentValue:v,label:q.labels[i]}))};}
 function draw(){const canvas=get('angleCanvas');if(!canvas)return;const box=canvas.getBoundingClientRect(),w=canvas.clientWidth,h=canvas.clientHeight,dpr=Math.min(devicePixelRatio||1,2);if(!w||!h)return;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);view={x:w/2+camera.x,y:h/2+camera.y,zoom:Math.min(w,h)/360*camera.zoom};ctx.translate(view.x,view.y);ctx.scale(view.zoom,view.zoom);const dark=document.body.classList.contains('dark'),ink=dark?'#f4f7ff':'#172033',g=geometry();
 for(const [i,r]of g.regions.entries()){const a=(r.start+g.rotation)*Math.PI/180,b=(r.start+r.currentValue+g.rotation)*Math.PI/180;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,55,-a,-b,true);ctx.closePath();ctx.fillStyle=dark?(i%2?'#637b9e':'#8196b4'):(i%2?'#dce8f8':'#ecf2fa');ctx.fill();ctx.strokeStyle='#000';ctx.lineWidth=1.3/view.zoom;ctx.stroke();const p=point(r.start+r.currentValue/2+g.rotation,82+(i%2)*12);ctx.fillStyle=ink;ctx.font=`600 ${14/view.zoom}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(r.label??displayValues(g.regions,model().total)[i]+'°',p.x,p.y);}
 for(const ray of g.rays){const p=point(ray.angle+g.rotation,132);ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(p.x,p.y);ctx.strokeStyle=ink;ctx.lineWidth=2/view.zoom;ctx.stroke();if(!ray.isFixed){ctx.beginPath();ctx.arc(p.x,p.y,8/view.zoom,0,Math.PI*2);ctx.fillStyle='#4c91ff';ctx.fill();}}
 for(const ray of g.rays){const edge=point(ray.angle+g.rotation,55);ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(edge.x,edge.y);ctx.strokeStyle='#000';ctx.lineWidth=1.3/view.zoom;ctx.stroke();}
 ctx.fillStyle=ink;ctx.beginPath();ctx.arc(0,0,3/view.zoom,0,Math.PI*2);ctx.fill();if(get('relationship'))get('relationship').textContent=displayValues(model().regions(),model().total).map(v=>v+'°').join(' + ')+` = ${model().total}°`;
 }
 function bind(){const c=get('angleCanvas');if(!c)return;const pos=e=>{const box=c.getBoundingClientRect();return pointerWorld(e,{left:box.left+c.clientLeft,top:box.top+c.clientTop},view)};
 c.onpointerdown=e=>{if(screen==='quiz'||active)return;const p=pos(e);let nearest=null,best=20/view.zoom;for(const ray of model().rays){if(ray.isFixed)continue;const h=point(ray.angle,132),d=Math.hypot(p.x-h.x,p.y-h.y);if(d<best){best=d;nearest=ray.id}}active=nearest?{id:nearest,pointer:e.pointerId}:{pan:true,pointer:e.pointerId,x:e.clientX,y:e.clientY,cx:camera.x,cy:camera.y};c.setPointerCapture(e.pointerId);e.preventDefault()};
 c.onpointermove=e=>{if(!active||e.pointerId!==active.pointer)return;if(active.pan){camera.x=active.cx+e.clientX-active.x;camera.y=active.cy+e.clientY-active.y}else model().move(active.id,pos(e));draw()};
 const end=e=>{if(active?.pointer===e.pointerId)active=null};c.onpointerup=end;c.onpointercancel=end;c.onlostpointercapture=end;c.onwheel=e=>{if(screen==='quiz')return;e.preventDefault();camera.zoom=Math.max(.55,Math.min(2.5,camera.zoom*Math.exp(-e.deltaY*.001)));draw()};
 }
 function resetCamera(){camera={x:0,y:0,zoom:1};draw()}
 function newQuestion(){q=quizQuestion(mode,tier);attempts=0;complete=false;shown=false;screen='quiz';camera={x:0,y:0,zoom:1};render()}
 function submit(e){e.preventDefault();if(complete)return;const raw=get('answer').value.trim();if(!raw)return;attempts++;if(Math.abs(Number(raw)-q.answer)<.001){complete=true;get('feedback').textContent=tr('Correct','Betul');get('nextQuestion').hidden=false;get('showWorking').hidden=false;get('submitAnswer').disabled=true;}else{get('feedback').textContent=mode==='straight'?tr('Think about the total angle on a straight line.','Fikirkan jumlah sudut pada garis lurus.'):tr('Think about the total angle around a point.','Fikirkan jumlah sudut di sekeliling titik.');if(attempts>=2)get('showWorking').hidden=false;}}
 function calculator(){const panel=get('calculator');panel.hidden=!panel.hidden;}
 function render(){active=null;dialog.innerHTML='<button class="close explorer-close" id="closeExplorer" aria-label="Close">×</button>';get('closeExplorer').onclick=()=>dialog.close();
 if(screen==='library'){dialog.insertAdjacentHTML('beforeend',`<div class="explorer-library"><span class="explorer-kicker">${tr('Exploration library','Perpustakaan penerokaan')}</span><h2>${tr('Explore mathematics','Terokai matematik')}</h2><details open><summary>${tr('Lines and Angles','Garis dan Sudut')}</summary><div class="library-items">${button('straight','Angles on a Straight Line','Sudut pada Garis Lurus')}${button('circle','Angles Around a Point','Sudut di Sekeliling Titik')}</div></details></div>`);for(const m of['straight','circle'])get(m).onclick=()=>{mode=m;screen='explore';shown=false;camera={x:0,y:0,zoom:1};render()};return;}
 dialog.insertAdjacentHTML('beforeend',`<div class="explorer-head"><div>${button('back','← Library','← Pustaka')}<span class="explorer-kicker">${tr('Lines and Angles','Garis dan Sudut')}</span><h2>${mode==='straight'?tr('Angles on a Straight Line','Sudut pada Garis Lurus'):tr('Angles Around a Point','Sudut di Sekeliling Titik')}</h2></div></div>`);get('back').onclick=()=>{screen='library';render()};
 if(screen==='tiers'){dialog.insertAdjacentHTML('beforeend',`<h3>${tr('Choose a quiz tier','Pilih tahap kuiz')}</h3><div class="tier-list">${TIERS.map((t,i)=>`<button data-tier="${i+1}"><strong>${tr('Tier','Tahap')} ${i+1} — ${tr(t[0],t[1])}</strong><span>${tr(t[2],t[3])}</span></button>`).join('')}</div>${button('returnExplore','Return to exploration','Kembali ke penerokaan')}`);dialog.querySelectorAll('[data-tier]').forEach(b=>b.onclick=()=>{tier=+b.dataset.tier;newQuestion()});get('returnExplore').onclick=()=>{screen='explore';render()};return;}
 const quiz=screen==='quiz';dialog.insertAdjacentHTML('beforeend',`<div class="explorer-grid"><section><canvas id="angleCanvas" class="angle-stage" aria-label="Interactive angle diagram"></canvas><p class="angle-instruction">${quiz?tr('Find','Cari')+' '+q.symbol:tr('Drag a blue handle. Drag empty space to pan; scroll to zoom.','Seret pemegang biru. Seret ruang kosong untuk alih; skrol untuk zum.')}</p>${quiz?'':button('resetView','Reset view','Tetapkan semula paparan')}</section><section class="explorer-side">${quiz?`<p>${tr('Tier','Tahap')} ${tier} — ${tr(TIERS[tier-1][0],TIERS[tier-1][1])}</p>${button('changeTier','Change Tier','Tukar Tahap')}<form id="answerForm" class="quiz-card"><label>${q.symbol} = <input id="answer" aria-label="${tr('Answer','Jawapan')}" type="number" step="any" inputmode="decimal" required>${q.algebra?'':'°'}</label><button id="submitAnswer" class="primary">${tr('Submit','Hantar')}</button><p id="feedback" aria-live="polite"></p></form><button id="showWorking" hidden>${tr('Show Working','Tunjuk Cara Kerja')}</button><pre id="working" hidden></pre><button id="nextQuestion" hidden>${tr('Next Question','Soalan Seterusnya')}</button>${button('calcToggle','Calculator','Kalkulator')}<div id="calculator" class="quiz-calculator" hidden></div>`:`<div class="total-card" ${shown?'':'hidden'}><span>${tr('Angle relationship','Hubungan sudut')}</span><strong id="relationship"></strong></div><div class="explorer-actions">${button('addRay','+ Add Ray','+ Tambah Sinar')}${button('removeRay','− Remove Ray','− Buang Sinar')}${button('toggleRelationship',shown?'Hide Relationship':'Show Relationship',shown?'Sembunyikan Hubungan':'Tunjuk Hubungan')}${button('test','Test Yourself','Uji Diri')}</div>`}</section></div>`);
 if(quiz){get('answerForm').onsubmit=submit;get('changeTier').onclick=()=>{screen='tiers';render()};get('nextQuestion').onclick=newQuestion;get('showWorking').onclick=()=>{get('working').hidden=false;get('working').textContent=q.steps.join('\n');complete=true;get('nextQuestion').hidden=false;get('submitAnswer').disabled=true;};get('calcToggle').onclick=calculator;mountCalculator(get('calculator'),{language,onClose:()=>{get('calculator').hidden=true;get('calcToggle').focus();}});}else{get('addRay').disabled=model().rays.length>=8;get('removeRay').disabled=mode==='straight'?model().rays.length===2:model().rays.length===1;get('addRay').onclick=()=>{model().add();render()};get('removeRay').onclick=()=>{model().remove();render()};get('toggleRelationship').onclick=()=>{shown=!shown;render()};get('test').onclick=()=>{shown=false;screen='tiers';render()};get('resetView').onclick=resetCamera;}
 draw();bind();}
 new ResizeObserver(()=>draw()).observe(dialog);dialog.onclose=()=>{active=null};trigger.onclick=()=>{screen='library';dialog.showModal();render()};return{open:()=>trigger.click()};
}
